/// <summary>
/// Controller class for ER price list report
/// </summary>
class AVAERWarehouseArrivalController extends ERFormatMappingRunBaseController
{


}

Method.Source:
/// <summary>
/// The main entrance of the controller
/// </summary>
/// <param name = "args">The arguments</param>
public static void main(Args args)
{
    if(!WMSParameters::find().AVAERWarehouseArrivalFormat)
    {
        throw Error(strFmt("@NDX:NXAWarehouseArrivalReportError", "@SYS336190", "@SYS54502"));
    }

    AVAERWarehouseArrivalController operation;
    operation = new AVAERWarehouseArrivalController(
        classStr(AVAERWarehouseArrivalService),
        methodStr(AVAERWarehouseArrivalService, generateReport),
        SysOperationExecutionMode::Synchronous);

    AVAERWarehouseArrivalContract contract = operation.getDataContractObject();

    contract.initFromArgs(args);
    operation.parmShowDialog(false);
    operation.startOperation();
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_purchId">PurchId</param>
public static void constructForAzureBlob(PurchId    _purchId)
{
    if(!WMSParameters::find().AVAERWarehouseArrivalFormat)
    {
        throw Error(strFmt("@NDX:NXAWarehouseArrivalReportError", "@SYS336190", "@SYS54502"));
    }

    AVAERWarehouseArrivalController operation;
    operation = new AVAERWarehouseArrivalController(
        classStr(AVAERWarehouseArrivalService),
        methodStr(AVAERWarehouseArrivalService, generateReport),
        SysOperationExecutionMode::Synchronous);

    AVAERWarehouseArrivalContract contract = operation.getDataContractObject();        

    contract.parmPrintToMemory(true);
    contract.initFromPurchId(_purchId);
    operation.parmShowDialog(false);
    operation.startOperation();
}

/// <summary>
/// Gets caption of the dialog.
/// </summary>
/// <returns>Caption of the dialog</returns>
public ClassDescription defaultCaption()
{
    ClassDescription batchDescription;
    batchDescription = "@NDX:NXAWarehouseArrival";
    return batchDescription;
}
